+using System;
+using System.Threading;
+using System.Threading.Tasks;
+using Leasing;
+using Microsoft.Extensions.Time.Testing;
+using Xunit;
+
+public class LeaseRenewerFakeTimeTests
+{
+    [Fact]
+    public async Task RenewAfterAsync_IncompleteBeforeDeadline_CompletesWhenTimeAdvances()
+    {
+        var fake = new FakeTimeProvider();
+        fake.SetUtcNow(DateTimeOffset.Parse("2024-01-01T00:00:00Z"));
+        var renewer = new LeaseRenewer(fake);
+
+        var task = renewer.RenewAfterAsync(TimeSpan.FromMinutes(5));
+        Assert.False(task.IsCompleted);
+
+        fake.Advance(TimeSpan.FromMinutes(5));
+        var stamp = await task;
+        Assert.Equal(DateTimeOffset.Parse("2024-01-01T00:05:00Z"), stamp);
+    }
+
+    [Fact]
+    public async Task RenewAfterAsync_Cancellation_Throws()
+    {
+        var fake = new FakeTimeProvider();
+        var renewer = new LeaseRenewer(fake);
+        using var cts = new CancellationTokenSource();
+
+        var task = renewer.RenewAfterAsync(TimeSpan.FromMinutes(5), cts.Token);
+        cts.Cancel();
+
+        await Assert.ThrowsAnyAsync<OperationCanceledException>(async () => await task);
+    }
+
+    [Fact]
+    public void DefaultConstructor_UsesSystemTimeProvider()
+    {
+        var renewer = new LeaseRenewer();
+        Assert.NotNull(renewer);
+    }
+}

steps.message:
LeaseRenewer is an instance class, so the clean seam is constructor injection of `TimeProvider`, which .NET provides specifically for both delays and timestamps. That avoids inventing a separate delay interface: the built-in `Task.Delay(TimeSpan, TimeProvider, CancellationToken)` overload makes the wait itself fake-time-aware, and `TimeProvider.GetUtcNow()` gives the timestamp from the same clock.

```csharp
public sealed class LeaseRenewer
{
    private readonly TimeProvider _timeProvider;

    public LeaseRenewer(TimeProvider? timeProvider = null) =>
        _timeProvider = timeProvider ?? TimeProvider.System;

    public async Task<DateTimeOffset> RenewAfterAsync(
        TimeSpan delay,
        CancellationToken cancellationToken = default)
    {
        await Task.Delay(delay, _timeProvider, cancellationToken);
        return _timeProvider.GetUtcNow();
    }
}
```

The default constructor argument is `TimeProvider.System`, so production keeps waiting on real timers and returning real UTC time; the observable behavior and cancellation contract are unchanged. Because both the delay and the returned timestamp read from the injected provider, a fake clock controls the whole method.

Tests inject `FakeTimeProvider` from Microsoft.Extensions.TimeProvider.Testing and drive the schedule explicitly, with no `Thread.Sleep` and no wall-clock waiting:

- A before/after test seeds the fake clock with `SetUtcNow`, starts `RenewAfterAsync(TimeSpan.FromMinutes(5))` without awaiting it, asserts the returned task is not yet completed, then calls `fakeTime.Advance(TimeSpan.FromMinutes(5))`; after that it awaits the task and asserts the timestamp equals the advanced fake time, proving the operation is incomplete before the deadline and completes exactly when fake time crosses it.
- A cancellation test starts the renewal, cancels the `CancellationTokenSource` before advancing the clock, and asserts the awaited call throws `TaskCanceledException` (an `OperationCanceledException`), proving cancellation still short-circuits the delay.
- A production-default assertion constructs the renewer with no provider and confirms it falls back to `TimeProvider.System`.

Built the production project, then ran `dotnet test fixtures/delayed-renewal/tests/DelayedRenewal.Tests.csproj`; all tests pass deterministically without real timers.
